<span class="line"><span style="color:#032F62;">$(</span><span style="color:#24292E;">BUILD</span><span style="color:#032F62;">)</span><span style="color:#24292E;">/zbar.wasm </span><span style="color:#032F62;">$(</span><span style="color:#24292E;">BUILD</span><span style="color:#032F62;">)</span><span style="color:#24292E;">/zbar.js: </span><span style="color:#032F62;">$(</span><span style="color:#24292E;">ZBAR_DEPS</span><span style="color:#032F62;">)</span><span style="color:#032F62;"> $(</span><span style="color:#24292E;">SRC</span><span style="color:#032F62;">)</span><span style="color:#24292E;">/export.c</span></span>
